CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS documentos (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), nome_arquivo VARCHAR(255) NOT NULL, caminho_relativo TEXT NOT NULL UNIQUE, hash_sha256 VARCHAR(64) NOT NULL, categoria VARCHAR(100) NOT NULL, subcategoria VARCHAR(100), linha_producao VARCHAR(100), maquina VARCHAR(100), versao INT NOT NULL DEFAULT 1, status VARCHAR(20) NOT NULL DEFAULT 'ATIVO', aprovado_por VARCHAR(150) DEFAULT 'SISTEMA_AUTO', total_paginas INT, criado_em TIMESTAMPTZ NOT NULL DEFAULT NOW(), atualizado_em TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_documentos_filtros ON documentos (status, categoria, maquina);
CREATE TABLE IF NOT EXISTS fragmentos_vetoriais (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), documento_id UUID NOT NULL REFERENCES documentos(id) ON DELETE CASCADE, indice_chunk INT NOT NULL, pagina_inicio INT, pagina_fim INT, conteudo_markdown TEXT NOT NULL, metadados JSONB DEFAULT '{}'::jsonb, embedding vector(1024), busca_textual tsvector GENERATED ALWAYS AS (to_tsvector('portuguese', coalesce(conteudo_markdown, ''))) STORED, criado_em TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_fragmentos_doc_id ON fragmentos_vetoriais (documento_id);
CREATE INDEX IF NOT EXISTS idx_fragmentos_embedding_hnsw ON fragmentos_vetoriais USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);
CREATE INDEX IF NOT EXISTS idx_fragmentos_busca_textual ON fragmentos_vetoriais USING gin (busca_textual);
CREATE TABLE IF NOT EXISTS historico_analises (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), usuario VARCHAR(150) DEFAULT 'operador_local', modo_operacao VARCHAR(50) NOT NULL, filtro_maquina VARCHAR(100), filtro_categoria VARCHAR(100), pergunta TEXT NOT NULL, resposta TEXT NOT NULL, documentos_utilizados JSONB DEFAULT '[]'::jsonb, modelo_llm VARCHAR(100), tempo_resposta_ms INT, feedback_operador SMALLINT, criado_em TIMESTAMPTZ NOT NULL DEFAULT NOW());